import queue
from collections import deque


def simulate(producers, maxsize, batch):
    if maxsize < 1 or batch < 1:
        raise ValueError('maxsize and batch must be >= 1')
    q = queue.Queue(maxsize=maxsize)
    pending = [deque(items) for items in producers]
    processed, full_events, ticks = [], 0, 0
    while any(pending) or not q.empty():
        ticks += 1
        for items in pending:
            if not items:
                continue
            try:
                q.put_nowait(items[0])
            except queue.Full:
                full_events += 1
            else:
                items.popleft()
        for _ in range(batch):
            try:
                processed.append(q.get_nowait())
            except queue.Empty:
                break
    return {'processed': processed, 'full_events': full_events, 'ticks': ticks}
